import{_ as d,o,c as t,a2 as c}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"Permission Capability Matrix - 权限能力矩阵","description":"","frontmatter":{},"headers":[],"relativePath":"permissionCapabilityMatrix.md","filePath":"permissionCapabilityMatrix.md","lastUpdated":1780847608000}'),r={name:"permissionCapabilityMatrix.md"};function a(i,e,n,s,u,l){return o(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="permission-capability-matrix-权限能力矩阵" tabindex="-1">Permission Capability Matrix - 权限能力矩阵</h1><p>本章节集中记录 AutoJs6 <code>6.7.0</code> 中对 Android 权限、系统服务、Root、Shizuku、无障碍或特定 Android 版本敏感的脚本能力.</p><p>源码基准:</p><ul><li>上游仓库: <code>SuperMonster003/AutoJs6</code></li><li>基准提交: <code>ed3eb10e88db5a8425fd94bdddefa4176e5e1c94</code></li><li>版本: <code>6.7.0</code></li><li>主包 SDK: <code>minSdk=24</code>, <code>targetSdk=36</code></li><li>INRT 包 SDK: <code>targetSdk=29</code></li></ul><p>源码依据:</p><ul><li><code>app/src/main/AndroidManifest.xml</code></li><li><code>app/src/main/java/org/autojs/autojs/runtime/ScriptRuntime.kt</code></li><li><code>app/src/main/java/org/autojs/autojs/runtime/api/augment/*</code></li><li><code>app/src/main/java/org/autojs/autojs/core/*</code></li></ul><p>机器可读数据:</p><ul><li><code>json/runtimeApiIndexData.json</code></li></ul><hr><h2 id="能力矩阵" tabindex="-1">能力矩阵</h2><table tabindex="0"><thead><tr><th>能力</th><th>API / 模块</th><th>依赖 / 权限</th><th>Android 版本边界</th><th>源码依据</th><th>文档入口</th></tr></thead><tbody><tr><td>无障碍服务</td><td><code>auto</code>, <code>automator</code>, <code>selector</code>, <code>UiObject</code>, <code>events.observeKey</code>, <code>events.observeToast</code>, <code>events.observeNotification</code></td><td>用户启用 AutoJs6 无障碍服务; 部分开关可借 root 或 <code>WRITE_SECURE_SETTINGS</code> 写入; 运行时通过 <code>AccessibilityBridge.ensureServiceStarted()</code> 获取服务</td><td>手势分发依赖 Android 无障碍能力; 部分 <code>UiObjectActions</code> 仅在较高 API 返回有效动作</td><td><code>augment/automator/Auto.kt</code><br><code>augment/automator/Automator.kt</code><br><code>core/accessibility/AccessibilityTool.kt</code><br><code>core/accessibility/AccessibilityServiceUsher.kt</code><br><code>core/automator/*</code></td><td><a href="./automator">Automator</a><br><a href="./uiSelectorType">UiSelector</a><br><a href="./uiObjectType">UiObject</a><br><a href="./events">Event</a></td></tr><tr><td>全局按键 / 手势 / 控件动作</td><td><code>click</code>, <code>longClick</code>, <code>press</code>, <code>swipe</code>, <code>gesture</code>, <code>back</code>, <code>home</code>, <code>recents</code>, <code>UiObject.click()</code> 等</td><td>优先依赖无障碍服务; <code>RootAutomator</code> 走 root / Shizuku 输入设备后端</td><td><code>Automator.captureScreen()</code> 使用无障碍截图时需 Android R / API 30+</td><td><code>augment/automator/Automator.kt</code><br><code>core/automator/UiObjectActions.kt</code><br><code>core/inputevent/RootAutomator.java</code></td><td><a href="./automator">Automator</a><br><a href="./uiObjectType">UiObject</a></td></tr><tr><td>Root 输入与 Root shell</td><td><code>new RootAutomator()</code>, <code>shell(cmd, true)</code>, <code>autojs.setRootMode(...)</code>, root 模式启动应用</td><td>root 可用, 或 <code>RootAutomator</code> 可使用 Shizuku 后端; root shell 会执行特权命令</td><td>受设备 root 状态和系统 SELinux / shell 权限限制</td><td><code>augment/automator/RootAutomator.kt</code><br><code>augment/automator/RootAutomatorNativeObject.kt</code><br><code>augment/shell/Shell.kt</code><br><code>runtime/api/ProcessShell.java</code><br><code>util/RootUtils.java</code></td><td><a href="./automator">Automator</a><br><a href="./shell">Shell</a><br><a href="./autojs">AutoJs6</a></td></tr><tr><td>Shizuku 命令与系统组件查询</td><td><code>shizuku.execCommand</code>, <code>shizuku.kill</code>, <code>shizuku.currentPackage</code>, <code>shizuku.currentActivity</code>, <code>shizuku.currentComponent</code></td><td>Shizuku 安装、服务运行、已授权且 <code>WrappedShizuku.isOperational()</code> 为真; manifest 声明 <code>moe.shizuku.manager.permission.API_V23</code></td><td>依赖 Shizuku 服务可用性和用户授权, 不等同于 root</td><td><code>augment/shizuku/Shizuku.kt</code><br><code>runtime/api/WrappedShizuku.kt</code><br><code>permission/ShizukuPermission.kt</code><br><code>core/shizuku/UserService.kt</code><br><code>AndroidManifest.xml</code></td><td><a href="./shizuku">Shizuku</a></td></tr><tr><td>当前前台包名 / Activity / Component</td><td><code>currentPackage</code>, <code>currentActivity</code>, <code>currentComponent</code>, <code>app.currentPackage</code>, <code>shizuku.currentPackage</code></td><td>默认可走无障碍; 可选择 root / Shizuku 模式</td><td>受 Android 后台限制和可访问窗口信息影响</td><td><code>augment/global/Global.kt</code><br><code>augment/app/App.kt</code><br><code>augment/shizuku/Shizuku.kt</code></td><td><a href="./global">Global</a><br><a href="./app">App</a><br><a href="./shizuku">Shizuku</a></td></tr><tr><td>悬浮窗</td><td><code>floaty.window</code>, <code>floaty.rawWindow</code>, <code>floaty.hasPermission</code>, <code>floaty.ensurePermission</code>, <code>console.show</code>, <code>console.build</code></td><td><code>android.permission.SYSTEM_ALERT_WINDOW</code>; 用户允许 &quot;显示在其他应用上层&quot;</td><td>Android O+ 使用新的 overlay window type; 具体展示还受系统厂商限制</td><td><code>AndroidManifest.xml</code><br><code>augment/floaty/Floaty.kt</code><br><code>runtime/api/Floaty.kt</code><br><code>permission/DisplayOverOtherAppsPermission.kt</code><br><code>util/FloatingPermission.java</code><br><code>ui/enhancedfloaty/util/WindowTypeCompat.java</code></td><td><a href="./floaty">Floaty</a><br><a href="./console">Console</a></td></tr><tr><td>剪贴板读取</td><td><code>floaty.getClip</code>, 全局 <code>getClip</code> / <code>setClip</code></td><td>Android Q / API 29+ 后台剪贴板限制下, 源码优先借助悬浮窗权限创建窗口后读取</td><td>Android Q+ 对后台剪贴板读取更严格; 无悬浮窗权限时可能失败或返回空</td><td><code>augment/floaty/Floaty.kt</code><br><code>augment/global/Global.kt</code><br><code>runtime/api/Floaty.kt</code><br><code>com/stardust/util/ClipboardUtil.java</code></td><td><a href="./floaty">Floaty</a><br><a href="./global">Global</a></td></tr><tr><td>屏幕截图 / MediaProjection</td><td><code>images.requestScreenCapture</code>, <code>images.requestScreenCaptureAsync</code>, <code>images.captureScreen</code>, 全局 <code>requestScreenCapture</code>, <code>captureScreen</code></td><td>用户授予 MediaProjection 截屏确认; 或系统 <code>appops PROJECT_MEDIA</code>; manifest 包含前台服务和 media projection 相关权限</td><td>Android 10+ 涉及前台服务类型; Android 14+ 对 MediaProjection 前台服务和一次性授权更严格; AutoJs6 通过 <code>ScreenCaptureRequester</code> / <code>ScreenCapturer</code> 管理会话</td><td><code>augment/images/Images.kt</code><br><code>runtime/api/Images.java</code><br><code>core/image/capture/ScreenCaptureRequester.java</code><br><code>core/image/capture/ScreenCapturer.java</code><br><code>core/image/capture/ScreenCapturerForegroundService.kt</code><br><code>permission/MediaProjectionPermission.kt</code><br><code>AndroidManifest.xml</code></td><td><a href="./image">Image</a></td></tr><tr><td>无障碍截图</td><td><code>automator.captureScreen()</code></td><td>已启用无障碍服务</td><td>源码中 <code>takeScreenshot</code> / 无障碍截图依赖 Android R / API 30+</td><td><code>augment/automator/Automator.kt</code><br><code>core/accessibility/AccessibilityService.kt</code></td><td><a href="./automator">Automator</a></td></tr><tr><td>通知发布与通知渠道</td><td><code>notice(...)</code>, <code>notice.channel.*</code>, <code>notice.ensureEnabled</code>, <code>events.observeNotification</code></td><td>系统通知开关; Android 13+ 需要 <code>POST_NOTIFICATIONS</code>; 监听通知需通知监听服务或无障碍通知观察</td><td>Android O / API 26+ 必须使用通知渠道; Android 13 / API 33+ 新增运行时通知权限</td><td><code>AndroidManifest.xml</code><br><code>augment/notice/Notice.kt</code><br><code>augment/notice/Channel.kt</code><br><code>runtime/api/Notice.kt</code><br><code>util/NotificationUtils.kt</code><br><code>core/notification/NotificationListenerService.kt</code><br><code>runtime/api/Events.java</code><br><code>core/accessibility/AccessibilityNotificationObserver.kt</code></td><td><a href="./notice">Notice</a><br><a href="./events">Event</a></td></tr><tr><td>系统设置写入</td><td><code>autojs.canModifySystemSettings</code>, <code>autojs.canWriteSecureSettings</code>, <code>device.setBrightness</code>, <code>device.setMusicVolume</code>, 指针位置相关能力</td><td><code>WRITE_SETTINGS</code> 需用户授权; <code>WRITE_SECURE_SETTINGS</code> 通常需 adb / root / 系统签名; manifest 已声明但不代表已授权</td><td>Android M / API 23+ 对修改系统设置有专门授权页; secure settings 更受系统保护</td><td><code>AndroidManifest.xml</code><br><code>permission/WriteSystemSettingsPermission.kt</code><br><code>permission/WriteSecureSettingsPermission.kt</code><br><code>util/SettingsUtils.java</code><br><code>augment/autojs/Autojs.kt</code><br><code>runtime/api/Device.java</code><br><code>core/accessibility/AccessibilityTool.kt</code></td><td><a href="./autojs">AutoJs6</a><br><a href="./device">Device</a></td></tr><tr><td>文件 / 外部存储</td><td><code>files.*</code>, <code>sqlite.open</code>, <code>zip.*</code>, <code>http.saveToFile</code>, <code>mediainfo.read</code>, <code>images.read/save</code></td><td>文件路径访问、媒体读取、外部存储权限或 Android scoped storage 策略; manifest 声明 READ/WRITE/MANAGE_EXTERNAL_STORAGE 与 READ_MEDIA_*</td><td>Android 10+ scoped storage; Android 11+ <code>MANAGE_EXTERNAL_STORAGE</code>; Android 13+ 分媒体类型读取权限; manifest 设置 <code>requestLegacyExternalStorage=true</code></td><td><code>AndroidManifest.xml</code><br><code>augment/files/Files.kt</code><br><code>runtime/api/Files.kt</code><br><code>permission/AllFilesAccessPermission.kt</code><br><code>external/fileprovider/AppFileProvider.java</code><br><code>augment/sqlite/SQLite.kt</code><br><code>augment/zip/Zip.kt</code><br><code>augment/http/ResponseBodyNativeObject.kt</code><br><code>augment/mediainfo/Mediainfo.kt</code></td><td><a href="./files">File</a><br><a href="./sqlite">SQLite</a><br><a href="./zip">Zip</a><br><a href="./http">HTTP</a><br><a href="./mediainfo">MediaInfo</a></td></tr><tr><td>网络请求 / WebSocket / WebView 加载</td><td><code>http.*</code>, <code>web.newWebSocket</code>, <code>new WebSocket</code>, <code>web.loadUrl</code>, <code>images.load</code> URL</td><td>manifest 声明 <code>INTERNET</code>; 网络状态读取依赖 <code>ACCESS_NETWORK_STATE</code> / <code>ACCESS_WIFI_STATE</code></td><td><code>INTERNET</code> 不是运行时弹窗权限; 明文 HTTP 还受网络安全配置和 <code>usesCleartextTraffic=true</code> 影响</td><td><code>AndroidManifest.xml</code><br><code>augment/http/Http.kt</code><br><code>runtime/api/Http.kt</code><br><code>augment/web/Web.kt</code><br><code>augment/web/WebSocket.kt</code><br><code>core/web/WebSocket.kt</code><br><code>augment/images/Images.kt</code></td><td><a href="./http">HTTP</a><br><a href="./web">Web</a><br><a href="./webSocketType">WebSocket</a><br><a href="./image">Image</a></td></tr><tr><td>OCR / 条码 / 二维码识别</td><td><code>ocr.mlkit</code>, <code>ocr.paddle</code>, <code>ocr.rapid</code>, <code>barcode</code>, <code>qrcode</code></td><td>传入图片时依赖图片文件 / bitmap; 不传图片而截图识别时依赖屏幕截图能力; Paddle 非 INRT 场景依赖插件或嵌入模型</td><td>MLKit / Paddle / Rapid 各自依赖库可用性; 区域裁剪受图片坐标边界限制</td><td><code>augment/ocr/Ocr.kt</code><br><code>augment/ocr/OcrMLKit.kt</code><br><code>augment/ocr/OcrPaddle.kt</code><br><code>augment/ocr/OcrRapid.kt</code><br><code>runtime/api/OcrMLKit.kt</code><br><code>runtime/api/OcrRapid.kt</code><br><code>core/plugin/ocr/PaddleOcrPluginHost.kt</code><br><code>augment/barcode/Barcode.kt</code><br><code>augment/barcode/QrCode.kt</code><br><code>runtime/api/WrappedBarcode.kt</code></td><td><a href="./ocr">OCR</a><br><a href="./barcode">Barcode</a><br><a href="./qrcode">QR Code</a></td></tr><tr><td>MediaInfo 原生库</td><td><code>mediainfo(path)</code>, <code>mediainfo.read(path)</code></td><td>本地媒体文件路径可访问; MediaInfo 原生库可用</td><td>原生库不可用会抛出 <code>MediaInfo library is not available</code>; stream 函数固定读取 index <code>0</code></td><td><code>augment/mediainfo/Mediainfo.kt</code><br><code>augment/mediainfo/MediainfoNativeObject.kt</code><br><code>org/mediainfo/android/MediaInfo.kt</code></td><td><a href="./mediainfo">MediaInfo</a><br><a href="./mediainfoNativeObjectType">MediainfoNativeObject</a></td></tr><tr><td>系统属性</td><td><code>sysprops.get</code>, <code>sysprops.list</code>, <code>sysprops.filter</code></td><td>普通属性可读; 受系统属性权限和 SELinux 限制; root / Shizuku 可提升命令读取能力但不是 <code>sysprops</code> 入口默认保证</td><td>Android 版本和厂商系统会影响可见属性</td><td><code>augment/sysprops/Sysprops.kt</code></td><td><a href="./sysprops">Sysprops</a></td></tr><tr><td>定时任务 / 精确闹钟 / 开机广播</td><td><code>tasks.*</code></td><td>manifest 声明 <code>USE_EXACT_ALARM</code>, <code>SCHEDULE_EXACT_ALARM</code>, <code>RECEIVE_BOOT_COMPLETED</code>; 用户系统策略可能限制精确闹钟和后台启动</td><td>Android 12+ 精确闹钟权限策略更严格</td><td><code>AndroidManifest.xml</code><br><code>augment/tasks/Tasks.kt</code><br><code>core/database/TimedTaskManager</code></td><td><a href="./tasks">Task</a></td></tr><tr><td>应用安装 / 卸载 / 包查询</td><td><code>app.install</code>, <code>app.uninstall</code>, <code>app.getAppName</code>, <code>app.getPackageName</code>, <code>app.openAppSetting</code></td><td>manifest 声明安装 / 删除包、查询全部包等权限; 部分操作需要用户确认或系统授权</td><td>Android 11+ 包可见性受 <code>QUERY_ALL_PACKAGES</code> 和 package visibility 影响</td><td><code>AndroidManifest.xml</code><br><code>augment/app/App.kt</code><br><code>runtime/api/AppUtils.kt</code></td><td><a href="./app">App</a></td></tr><tr><td>震动 / 设备状态</td><td><code>device.vibrate</code>, <code>device.getBattery</code>, <code>device.getScreenWidth</code>, <code>device.keepScreenOn</code></td><td><code>VIBRATE</code>, <code>WAKE_LOCK</code>; 大多设备信息读取无需运行时权限</td><td>厂商系统可能限制后台保活与保持亮屏</td><td><code>AndroidManifest.xml</code><br><code>augment/device/Device.kt</code><br><code>runtime/api/Device.java</code></td><td><a href="./device">Device</a></td></tr><tr><td>传感器</td><td><code>sensors.register</code>, <code>sensors.on</code></td><td>设备硬件传感器可用; 某些传感器可能受系统隐私策略限制</td><td>Android 版本和设备硬件决定可用传感器列表与采样频率</td><td><code>augment/sensors/Sensors.kt</code></td><td><a href="./sensors">Sensor</a></td></tr><tr><td>录音 / 录制</td><td><code>recorder.*</code></td><td>manifest 声明 <code>RECORD_AUDIO</code>; 录音需用户运行时授权</td><td>Android 6+ 危险权限需动态授权; 后台录音受系统策略限制</td><td><code>AndroidManifest.xml</code><br><code>augment/recorder/Recorder.kt</code></td><td><a href="./recorder">Recorder</a></td></tr></tbody></table><h2 id="使用建议" tabindex="-1">使用建议</h2><ul><li>知识库回答权限问题时, 优先引用本矩阵和具体模块页面的 &quot;源码依据&quot; 小节.</li><li>manifest 中存在的权限不代表脚本调用时已获得授权; 仍需结合运行时授权、系统开关和设备策略判断.</li><li>Root / Shizuku / 无障碍是三种不同执行通道, 不能互相等价. API 文档若标注了其中之一, 应按实际源码路径回答.</li></ul>',13)])])}const b=d(r,[["render",a]]);export{p as __pageData,b as default};
